// Keeps the trending searches that are about F1. Distinctive names count on their own; names that are
// common outside F1 (Hamilton, Russell, Norris, Ferrari, Qatar...) count only if one of the news stories
// Google shows next to the trend mentions F1. Each country+search is reported once per 24 hours.
const STRONG = ['f1', 'formula 1', 'formula one', 'fórmula 1', 'formule 1', 'grand prix', 'gran premio', 'grande prêmio',
  'verstappen', 'leclerc', 'piastri', 'antonelli', 'hadjar', 'bearman', 'colapinto', 'gasly', 'hulkenberg', 'hülkenberg',
  'albon', 'bortoleto', 'tsunoda', 'bottas', 'ocon', 'fia', 'liberty media', 'toto wolff', 'horner', 'vasseur', 'lusail', 'yas marina'];
const CONTEXT_NEEDED = ['hamilton', 'russell', 'norris', 'alonso', 'sainz', 'perez', 'pérez', 'checo', 'stroll', 'lawson',
  'ferrari', 'mercedes', 'mclaren', 'red bull', 'williams', 'alpine', 'haas', 'aston martin', 'cadillac', 'racing bulls',
  'qatar', 'catar', 'abu dhabi', 'abu dabi', 'las vegas'];
const F1_CONTEXT = /\bf1\b|formula (1|one)|fórmula 1|fórmula uno|grand prix|gran premio|grande prêmio|\bgp\b/i;
const has = (text, k) => new RegExp(`(^|[^\\p{L}\\p{N}])${k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}($|[^\\p{L}\\p{N}])`, 'iu').test(text);
const dec = (s) => (s || '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim();
const countries = $('Countries').all().map((i) => i.json);
const state = $getWorkflowStaticData('global');
state.seen = state.seen || {};
const now = Date.now();
for (const k of Object.keys(state.seen)) if (now - state.seen[k] > 24 * 36e5) delete state.seen[k];
const hits = [];
$input.all().forEach((r, i) => {
  const geo = countries[i]?.geo ?? '?';
  const body = String(r.json.body ?? r.json.data ?? '');
  for (const [, s] of body.matchAll(/<item>([\s\S]*?)<\/item>/g)) {
    const title = dec((s.match(/<title>([\s\S]*?)<\/title>/) || [])[1]);
    const traffic = dec((s.match(/<ht:approx_traffic>([\s\S]*?)<\/ht:approx_traffic>/) || [])[1]);
    const started = dec((s.match(/<pubDate>([\s\S]*?)<\/pubDate>/) || [])[1]);
    const news = [...s.matchAll(/<ht:news_item>([\s\S]*?)<\/ht:news_item>/g)].map(([, n]) => ({
      title: dec((n.match(/<ht:news_item_title>([\s\S]*?)<\/ht:news_item_title>/) || [])[1]),
      source: dec((n.match(/<ht:news_item_source>([\s\S]*?)<\/ht:news_item_source>/) || [])[1]),
      url: dec((n.match(/<ht:news_item_url>([\s\S]*?)<\/ht:news_item_url>/) || [])[1]),
    }));
    const newsText = news.map((n) => n.title).join(' | ');
    const strong = STRONG.filter((k) => has(title, k));
    const weak = CONTEXT_NEEDED.filter((k) => has(title, k));
    const isF1 = strong.length > 0 || (weak.length > 0 && F1_CONTEXT.test(newsText));
    if (!isF1) continue;
    const key = `${geo}|${title.toLowerCase()}`;
    if (state.seen[key]) continue;
    state.seen[key] = now;
    hits.push({ geo, title, traffic, started, news, terms: [...strong, ...weak] });
  }
});
if (!hits.length) return [];
return [{ json: { hits, url: 'https://www.paddockintel.com/sitemap.xml' } }];

// Adds what PaddockIntel already has on each trending topic (from our sitemap: recent pages whose
// address contains the name, in the country's language when it exists) and builds the email.
const { hits } = $('F1 trends').first().json;
const xml = String($input.first().json.body ?? $input.first().json.data ?? '');
const pages = [...xml.matchAll(/<url>\s*<loc>([^<]+)<\/loc>\s*<lastmod>([^<]+)<\/lastmod>/g)].map(([, loc, mod]) => ({ loc, mod: Date.parse(mod) || 0 }));
const LANG = { US: 'en', GB: 'en', MX: 'es', ES: 'es', AR: 'es', BR: 'pt' };
const GENERIC = new Set(['f1', 'formula 1', 'formula one', 'fórmula 1', 'formule 1', 'grand prix', 'gran premio', 'grande prêmio', 'fia']);
const slugify = (s) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const langOf = (u) => (/paddockintel\.com\/es\//.test(u) ? 'es' : /paddockintel\.com\/pt\//.test(u) ? 'pt' : 'en');
const ours = (h) => {
  const keys = h.terms.filter((t) => !GENERIC.has(t)).map(slugify).filter(Boolean);
  if (!keys.length) return [];
  const since = Date.now() - 21 * 864e5;
  const found = pages.filter((p) => p.mod >= since && keys.some((k) => p.loc.includes(k)));
  const want = LANG[h.geo] || 'en';
  const pick = found.filter((p) => langOf(p.loc) === want);
  return (pick.length ? pick : found.filter((p) => langOf(p.loc) === 'en')).sort((a, b) => b.mod - a.mod).slice(0, 3);
};
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;');
const FLAG = { US: '🇺🇸', GB: '🇬🇧', MX: '🇲🇽', ES: '🇪🇸', AR: '🇦🇷', BR: '🇧🇷' };
const cards = hits.map((h) => {
  const o = ours(h);
  const news = h.news.slice(0, 3).map((n) => `<li>${esc(n.source)}: <a href="${esc(n.url)}">${esc(n.title)}</a></li>`).join('');
  const mine = o.length
    ? `<p style="margin:6px 0 0"><b>Lo nuestro:</b></p><ul>${o.map((p) => `<li><a href="${esc(p.loc)}">${esc(p.loc.replace('https://www.paddockintel.com', ''))}</a> (${new Date(p.mod).toISOString().slice(0, 10)})</li>`).join('')}</ul>`
    : `<p style="margin:6px 0 0;color:#b45309"><b>No tenemos nada de los últimos 21 días sobre esto.</b></p>`;
  return `<div style="border:1px solid #ddd;border-radius:10px;padding:12px 14px;margin:0 0 12px">
    <div style="font:600 16px Arial,sans-serif">${FLAG[h.geo] || ''} ${esc(h.geo)} · “${esc(h.title)}” · ${esc(h.traffic)} búsquedas</div>
    <div style="font:12px Arial,sans-serif;color:#666">tendencia desde ${esc(h.started)}</div>
    <p style="margin:8px 0 0"><b>Lo que Google muestra al lado:</b></p><ul>${news}</ul>${mine}</div>`;
}).join('');
const top = hits[0];
return [{ json: {
  subject: `Tendencia F1: “${top.title}” en ${top.geo} (${top.traffic})${hits.length > 1 ? ` y ${hits.length - 1} más` : ''}`,
  html: `<div style="max-width:660px;font-family:Arial,sans-serif">${cards}<p style="color:#888">Google Trends, “Trending now”. El volumen es aproximado; la tendencia suele durar horas.</p></div>`,
} }];
